// ELEMENTS:
// 1. Navy com o filete vermelho no topo
// 2. Label + número grande a contar (anim.text, ex. "60 dias") + sub
// 3. Calendário: uma célula por dia (10 por linha) que se enche de azul royal em sequência,
//    o 1.º dia com uma casinha, o último a vermelho
// 4. Carimbo vermelho (badge) a cair rodado em badgeAt (s)
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(2));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.07, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const CalendarioPrazo: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const label = String(p.label ?? "").trim();
  const sub = String(p.sub ?? "").trim();
  const badge = String(p.badge ?? "").trim();
  const badgeAt = Number(p.badgeAt ?? 3.5) || 3.5;
  const text = String(anim.text ?? "").trim();
  const m = text.match(/\d+/);
  const days = Math.max(1, Math.min(90, m ? parseInt(m[0], 10) : 30));
  const unit = m ? text.slice((m.index ?? 0) + m[0].length).trim() : "";

  const show = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const fill = interpolate(f, [Math.round(0.5 * fps), Math.round(2.9 * fps)], [0, days], { ...clamp, easing: Easing.inOut(Easing.cubic) });
  const cols = 10;
  const cell = 78 * u;
  const gap = 12 * u;
  const stamp = show(badgeAt, 0.45, BACK);

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 44 * u }}>
        {label ? (
          <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 30 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: MIST, opacity: show(0.05) }}>
            <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
            {label}
          </div>
        ) : null}
        <div style={{ display: "flex", alignItems: "baseline", gap: 22 * u, opacity: show(0.15) }}>
          <span style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 210 * u, lineHeight: 1, color: WHITE, fontVariantNumeric: "lining-nums tabular-nums" }}>{Math.round(fill)}</span>
          <span style={{ fontFamily: FONTS.display, fontWeight: 800, fontSize: 80 * u, color: WHITE }}>{unit}</span>
        </div>
        <div style={{ position: "relative", display: "grid", gridTemplateColumns: `repeat(${cols}, ${cell}px)`, gap }}>
          {Array.from({ length: days }, (_, i) => {
            const on = fill > i + 0.5;
            const last = i === days - 1;
            const appear = show(0.1 + (i % cols) * 0.02 + Math.floor(i / cols) * 0.04, 0.4);
            return (
              <div key={i} style={{ width: cell, height: cell, borderRadius: 12 * u, boxSizing: "border-box", border: `${2 * u}px solid ${on ? (last ? RED : BLUE) : "rgba(255,255,255,0.22)"}`, background: on ? (last ? RED : BLUE) : "transparent", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONTS.mono, fontSize: 24 * u, color: on ? WHITE : "rgba(255,255,255,0.4)", opacity: appear, transform: `scale(${on && fill < i + 2 ? 1.12 : 1})` }}>
                {i === 0 ? (
                  <svg width={40 * u} height={40 * u} viewBox="0 0 40 40"><path d="M6 20 L20 8 L34 20 M10 17 V33 H30 V17" fill="none" stroke={WHITE} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" /></svg>
                ) : (i + 1) % 10 === 0 || last ? i + 1 : ""}
              </div>
            );
          })}
          {badge ? (
            <div style={{ position: "absolute", right: -30 * u, bottom: -60 * u, background: RED, color: WHITE, borderRadius: 999, padding: `${22 * u}px ${40 * u}px`, fontFamily: FONTS.body, fontWeight: 700, fontSize: 34 * u, letterSpacing: "0.12em", textTransform: "uppercase", transform: `rotate(${-8 + (1 - stamp) * -20}deg) scale(${stamp > 0 ? 0.6 + 0.4 * stamp + (1 - stamp) * 0.8 : 0})`, opacity: stamp, boxShadow: "0 16px 36px rgba(0,0,0,0.4)", border: `${4 * u}px solid ${WHITE}` }}>
              {badge}
            </div>
          ) : null}
        </div>
        {sub ? <div style={{ marginTop: 40 * u, fontFamily: FONTS.display, fontWeight: 300, fontSize: 52 * u, color: WHITE, textAlign: "center", maxWidth: 900 * u, opacity: show(1.2), transform: `translateY(${(1 - show(1.2)) * 24 * u}px)` }}>{sub}</div> : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default CalendarioPrazo;
